Example implementation paths:

```javascript
// Node.js example using MongoDB with Express
const express = require('express');
const app = express();
const db = require('./mongoDB');

app.use(express.json());

app.post('/order', (req, res) => {
  const { item_name, price } = req.body;

  // Customer fulfillment query to MongoDB
  db.collection('orders').insertOne({ item_name, price }, (err, res) => {
    if (err) {
      console.error(err);
      res.status(500).send("Error handling your request!");
    } else {
      res.send("Order received!");
    }
  });
});

app.listen(3000, () => console.log('listening for requests'));
```

Ultimately, the decision to use Node.js and MongoDB depends on your team's expertise, the application's requirements, and the stakeholders' needs. I would recommend running a PoC and weighing the pros and cons before making a final decision.

